    addi s0, sp, 16          # s0 = frame pointer (caller's sp)
    sw   ra, -4(s0)
    sw   t0, -8(s0)          # saved caller's frame pointer

    sw   zero, -12(s0)          # init a = 0
    sw   zero, -16(s0)          # init b = 0
