    addi t0, s0, -12          # &a
    push t0
    pop  t1
    pop  t0
    sw   t0, 0(t1)           # *arg = value
    lw   t0, 0(sp)
    addi t0, t0, 1
    sw   t0, 0(sp)          # matched++
    lw   t0, 0(sp)          # all directives matched -> count
    j    __L_scan_3_done
__L_scan_3_fail:
    lw   t0, 0(sp)
    bnez t0, __L_scan_3_done
    mv   t0, a1             # nothing matched -> 0 (bad char) or -1 (EOF)
__L_scan_3_done:
