    push t0
    pop  t0
    lw   t0, -12(s0)          # read a
    push t0
    li   t0, 0
    push t0
    pop  t1
    pop  t0
    sub  t0, t0, t1
    seqz t0, t0
    push t0
    pop  t0
    beqz t0, __L_else_4
    j    __L_while_end_2
    j    __L_endif_5
__L_else_4:
__L_endif_5:
    addi sp, sp, -4          # scanf: matched-count slot
    sw   zero, 0(sp)
    call __read_int          # %d
    blez a1, __L_scan_6_fail
    push a0
    addi t0, s0, -16          # &b
    push t0
    pop  t1
    pop  t0
    sw   t0, 0(t1)           # *arg = value
    lw   t0, 0(sp)
    addi t0, t0, 1
    sw   t0, 0(sp)          # matched++
    lw   t0, 0(sp)          # all directives matched -> count
    j    __L_scan_6_done
__L_scan_6_fail:
    lw   t0, 0(sp)
    bnez t0, __L_scan_6_done
    mv   t0, a1             # nothing matched -> 0 (bad char) or -1 (EOF)
__L_scan_6_done:
